6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":2630,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 9.10\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T71e,"])self.__next_f.push([1,"It is clearly stated here that the Supreme Lord, although aloof from all the activities of the material world, remains the supreme director. The Supreme Lord is the supreme will and the background of this material manifestation, but the management is being conducted by material nature. Kṛṣṇa also states in Bhagavad-gītā that of all the living entities in different forms and species, “I am the father.” The father gives seeds to the womb of the mother for the child, and similarly the Supreme Lord by His mere glance injects all the living entities into the womb of material nature, and they come out in their different forms and species, according to their last desires and activities. All these living entities, although born under the glance of the Supreme Lord, take their different bodies according to their past deeds and desires. So the Lord is not directly attached to this material creation. He simply glances over material nature; material nature is thus activated, and everything is created immediately. Because He glances over material nature, there is undoubtedly activity on the part of the Supreme Lord, but He has nothing to do with the manifestation of the material world directly. This example is given in the smṛti: when there is a fragrant flower before someone, the fragrance is touched by the smelling power of the person, yet the smelling and the flower are detached from one another. There is a similar connection between the material world and the Supreme Personality of Godhead; actually He has nothing to do with this material world, but He creates by His glance and ordains. In summary, material nature, without the superintendence of the Supreme Personality of Godhead, cannot do anything. Yet the Supreme Personality is detached from all material activities."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":2630,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"10\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 10\",\"advanced_view_url_path\":\"/en/library/bg/9/advanced-view/#bb2331\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/9/10/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/9/10/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/9